-    // explicitly: where the extension is detected it is enabled by default, and
-    // a plain start-up should stay quiet.
-    if (!FLAG_IS_DEFAULT(UseZalasr)) {
-      warning("UseZalasr requires a JVM built with a toolchain using the "
